{
  "root_cause": "The Checkboxes component only attaches a click listener, and the exclusive logic for "None of these" only unchecks other exclusive inputs with the same name, not all inputs in the same exclusive group. Keyboard interaction (Space) triggers a change event, not a click event, so the exclusive logic never runs. Additionally, the unCheckAllInputsExcept method incorrectly selects only exclusive inputs with the same name, failing to clear non-exclusive symptom checkboxes when the exclusive checkbox has a different name.",
  "repair_strategy": "Replace the click event listener with a change event listener to capture both mouse and keyboard interactions. Rewrite unCheckAllInputsExcept to uncheck all checkboxes in the same exclusive group (or same name if no group). Rewrite unCheckExclusiveInputs to select exclusive inputs by group when available.",
  "edits": [
    {
      "path": "packages/nhsuk-frontend/src/nhsuk/components/checkboxes/checkboxes.js",
      "sha256": "b12e3c7a52e09c981155d2f727c5eb8358d420a487177c9a1e722c19da4c8af0",
      "before": "    // Handle events
    this.$root.addEventListener('click', (event) => this.handleClick(event))",
      "after": "    // Handle events
    this.$root.addEventListener('change', (event) => this.handleClick(event))"
    },
    {
      "path": "packages/nhsuk-frontend/src/nhsuk/components/checkboxes/checkboxes.js",
      "sha256": "b12e3c7a52e09c981155d2f727c5eb8358d420a487177c9a1e722c19da4c8af0",
      "before": "  /**
   * Uncheck exclusive inputs
   *
   * Find any checkbox inputs with the same checkbox group value and the 'exclusive' behaviour,
   * and uncheck them. This helps prevent someone checking both a regular checkbox and a
   * "None of these" checkbox in the same fieldset.
   *
   * @param {HTMLInputElement} $input - Checkbox input
   */
  unCheckAllInputsExcept($input) {
    const { checkboxExclusiveGroup: exclusiveGroup } = $input.dataset

    const allInputsWithSameNameAndExclusiveBehaviour =
      document.querySelectorAll(
        `input[type="checkbox"][data-checkbox-exclusive][name="${$input.name}"]`
      )

    allInputsWithSameNameAndExclusiveBehaviour.forEach(($exclusiveInput) => {
      const hasSameFormOwner = $input.form === $exclusiveInput.form

      // Uncheck the exclusive input only. When no group is set, fall back to
      // GOV.UK Frontend behaviour and uncheck all with the same name attribute
      if (hasSameFormOwner) {
        this.setInputState($exclusiveInput, false, exclusiveGroup)
      }
    })
  }",
      "after": "  /**
   * Uncheck all other inputs in the same exclusive group (or same name if no group)
   *
   * When an exclusive checkbox (e.g. "None of these") is checked, uncheck all other
   * checkboxes in the same group to enforce mutual exclusivity.
   *
   * @param {HTMLInputElement} $input - Checkbox input that was checked
   */
  unCheckAllInputsExcept($input) {
    const { checkboxExclusiveGroup: exclusiveGroup } = $input.dataset

    let $inputsToUncheck
    if (exclusiveGroup) {
      $inputsToUncheck = $input.form.querySelectorAll(
        `input[type="checkbox"][data-checkbox-exclusive-group="${exclusiveGroup}"]`
      )
    } else {
      $inputsToUncheck = $input.form.querySelectorAll(
        `input[type="checkbox"][name="${$input.name}"]`
      )
    }

    $inputsToUncheck.forEach(($inputToUncheck) => {
      if ($inputToUncheck !== $input) {
        this.setInputState($inputToUncheck, false, exclusiveGroup)
      }
    })
  }"
    },
    {
      "path": "packages/nhsuk-frontend/src/nhsuk/components/checkboxes/checkboxes.js",
      "sha256": "b12e3c7a52e09c981155d2f727c5eb8358d420a487177c9a1e722c19da4c8af0",
      "before": "  /**
   * Uncheck exclusive inputs
   *
   * Find any checkbox inputs with the same checkbox group value and the 'exclusive' behaviour,
   * and uncheck them. This helps prevent someone checking both a regular checkbox and a
   * "None of these" checkbox in the same fieldset.
   *
   * @param {HTMLInputElement} $input - Checkbox input
   */
  unCheckExclusiveInputs($input) {
    const { checkboxExclusiveGroup: exclusiveGroup } = $input.dataset

    const allInputsWithSameName = document.querySelectorAll(
      `input[type="checkbox"][name="${$input.name}"]`
    )

    allInputsWithSameName.forEach(($inputWithSameName) => {
      const hasSameFormOwner = $input.form === $inputWithSameName.form

      // Uncheck all with same exclusive group by default, otherwise fall back to
      // GOV.UK Frontend behaviour and uncheck all with the same name attribute
      if (hasSameFormOwner && $inputWithSameName !== $input) {
        this.setInputState($inputWithSameName, false, exclusiveGroup)
      }
    })
  }",
      "after": "  /**
   * Uncheck exclusive inputs in the same group
   *
   * When a regular checkbox is checked, uncheck any exclusive checkboxes
   * in the same exclusive group (or same name if no group).
   *
   * @param {HTMLInputElement} $input - Checkbox input that was checked
   */
  unCheckExclusiveInputs($input) {
    const { checkboxExclusiveGroup: exclusiveGroup } = $input.dataset

    let $exclusiveInputs
    if (exclusiveGroup) {
      $exclusiveInputs = $input.form.querySelectorAll(
        `input[type="checkbox"][data-checkbox-exclusive][data-checkbox-exclusive-group="${exclusiveGroup}"]`
      )
    } else {
      $exclusiveInputs = $input.form.querySelectorAll(
        `input[type="checkbox"][data-checkbox-exclusive][name="${$input.name}"]`
      )
    }

    $exclusiveInputs.forEach(($exclusiveInput) => {
      if ($exclusiveInput !== $input) {
        this.setInputState($exclusiveInput, false, exclusiveGroup)
      }
    })
  }"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can now select the 'No symptoms' exclusive checkbox and have any previously selected symptom checkboxes automatically cleared, satisfying WCAG 2.1.1 (Keyboard) and 2.4.3 (Focus Order).",
  "functional_risks": [
    "The change event fires for programmatic changes, but the handler returns early when the checkbox is unchecked, so no adverse effect is expected.",
    "The new group-based selection might affect other checkbox groups if they share the same group attribute unexpectedly, but the attribute is designed for this purpose."
  ],
  "verification_requirements": [
    "Using only the keyboard (Tab to navigate, Space to check), verify that checking cough and fever then checking 'No symptoms' clears cough and fever.",
    "Verify that mouse clicking continues to work as before.",
    "Confirm that conditional reveals linked via aria-controls still synchronize correctly for both mouse and keyboard interactions.",
    "Ensure no errors are thrown when initializing the component on pages that use it.",
    "Verify the regression guard: choosing 'Do not contact me' after ticking a contact method works."
  ]
}
